cat > /tmp/test_sorting.js << 'EOF'
const dates = [
  { name: 'Gym', when: '2 Nov', date: '2026-11-02' },
  { name: 'Music', when: '30 Oct', date: '2026-10-30' }
];

const sorted = dates.sort((a, b) => a.when.localeCompare(b.when) || a.name.localeCompare(b.name));
console.log('Sorted by "when":', sorted.map(d => d.date));
console.log('Expected:', ['2026-10-30', '2026-11-02']);
EOF
node /tmp/test_sorting.js
